def is_balanced(code):
    stack = []
    for char in code:
        if char == '"':
            # Skip until the end of the string literal
            i = code.index('"', code.index('"') + 1)
            code = code[:i] + code[i+1:]
        elif char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if (top == '(' and char != ')') or (top == '[' and char != ']') or (top == '{' and char != '}'):
                return False
        # Ignore all other characters
    return not stack
